import * as T from './vendor/three.module.js';
export const CIRCUIT_WAYPOINTS=Object.freeze([{x:0,z:-150},{x:50,z:-160},{x:120,z:-140},{x:170,z:-90},{x:190,z:-20},{x:170,z:60},{x:130,z:120},{x:90,z:160},{x:40,z:180},{x:-20,z:200},{x:-90,z:230},{x:-160,z:250},{x:-220,z:220},{x:-250,z:160},{x:-240,z:100},{x:-200,z:40},{x:-170,z:-10},{x:-175,z:-45},{x:-195,z:-65},{x:-210,z:-110},{x:-190,z:-160},{x:-140,z:-190},{x:-80,z:-200},{x:-30,z:-180},{x:-10,z:-155}]);
const wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));
export class CircuitPath{
 constructor({x=-6000,z=6000,samples=2048,waypoints=CIRCUIT_WAYPOINTS,width=16}={}){
  this.originX=x;this.originZ=z;this.count=samples;this.width=width;
  const curve=new T.CatmullRomCurve3(waypoints.map(p=>new T.Vector3(p.x+x,0,p.z+z)),true,'centripetal');curve.arcLengthDivisions=8192;curve.updateArcLengths();this.length=curve.getLength();this.ds=this.length/samples;
  this.x=new Float64Array(samples+1);this.z=new Float64Array(samples+1);this.heading=new Float64Array(samples+1);this.curvature=new Float64Array(samples+1);
  for(let i=0;i<=samples;i++){const p=curve.getPointAt(i/samples);this.x[i]=p.x;this.z[i]=p.z;}
  for(let i=0;i<samples;i++){const a=(i-2+samples)%samples,b=(i+2)%samples;this.heading[i]=Math.atan2(-(this.x[b]-this.x[a]),-(this.z[b]-this.z[a]));}
  this.heading[samples]=this.heading[0];for(let i=0;i<samples;i++)this.curvature[i]=wrap(this.heading[(i+2)%samples]-this.heading[(i-2+samples)%samples])/(4*this.ds);this.curvature[samples]=this.curvature[0];
 }
 sampleAtDistance(s,out){const n=this.count,d=((s%this.length)+this.length)%this.length/this.ds,i=Math.min(n-1,Math.floor(d)),f=d-i;out.x=this.x[i]+(this.x[i+1]-this.x[i])*f;out.z=this.z[i]+(this.z[i+1]-this.z[i])*f;out.heading=this.heading[i]+wrap(this.heading[i+1]-this.heading[i])*f;out.curvature=this.curvature[i]+(this.curvature[i+1]-this.curvature[i])*f;out.dx=-Math.sin(out.heading);out.dz=-Math.cos(out.heading);return out;}
 nearest(x,z,around,window=35){let best=around,error=Infinity;const start=Math.floor(around/this.ds),span=Math.ceil(window/this.ds);for(let o=-span;o<=span;o++){const raw=start+o,i=((raw%this.count)+this.count)%this.count,dx=this.x[i+1]-this.x[i],dz=this.z[i+1]-this.z[i],f=Math.max(0,Math.min(1,((x-this.x[i])*dx+(z-this.z[i])*dz)/(dx*dx+dz*dz))),ex=x-this.x[i]-dx*f,ez=z-this.z[i]-dz*f,d=ex*ex+ez*ez;if(d<error){error=d;best=(raw+f)*this.ds;}}return best;}
}
export function buildCircuit(scene,physics,path,asphalt=null){
 const root=new T.Group();root.name='SOLANA RACEWAY';scene.add(root);const walls=[],count=480,scratch={x:0,z:0,heading:0,curvature:0,dx:0,dz:0},rows=[],vertices=[],uvs=[],colors=[],indices=[];
 // Asphalt + alternating rumble strips share one material and draw call.
 for(let i=0;i<=count;i++){path.sampleAtDistance(i/count*path.length,scratch);const rx=Math.cos(scratch.heading),rz=-Math.sin(scratch.heading);for(const side of [-8.7,-8,8,8.7]){vertices.push(scratch.x+rx*side,.025,scratch.z+rz*side);uvs.push((side+9)/4,i*path.length/count/5);const red=i%2?1:.25;colors.push(side===-8||side===8?.25:1,side===-8||side===8?.25:red,side===-8||side===8?.25:red);}rows.push([scratch.x,scratch.z,scratch.heading]);}
 for(let i=0;i<count;i++)for(let j=0;j<3;j++){const a=i*4+j,b=a+4;indices.push(a,b,a+1,a+1,b,b+1);}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(vertices,3));g.setAttribute('uv',new T.Float32BufferAttribute(uvs,2));g.setAttribute('color',new T.Float32BufferAttribute(colors,3));g.setIndex(indices);g.computeVertexNormals();
 const mat=new T.MeshStandardMaterial({color:0xffffff,vertexColors:true,map:asphalt,roughness:.93,side:T.DoubleSide}),road=new T.Mesh(g,mat);road.receiveShadow=true;root.add(road);
 const wallGeo=new T.BoxGeometry(.5,1.1,1),wallMat=new T.MeshStandardMaterial({color:0xb7bdc0,roughness:.7}),wallMesh=new T.InstancedMesh(wallGeo,wallMat,count*2),dummy=new T.Object3D();root.add(wallMesh);
 let cursor=0;for(let i=0;i<count;i++)for(const side of [-1,1]){const a=rows[i],b=rows[i+1],ax=a[0]+Math.cos(a[2])*9.5*side,az=a[1]-Math.sin(a[2])*9.5*side,bx=b[0]+Math.cos(b[2])*9.5*side,bz=b[1]-Math.sin(b[2])*9.5*side,len=Math.hypot(bx-ax,bz-az),heading=Math.atan2(-(bx-ax),-(bz-az)),x=(ax+bx)/2,z=(az+bz)/2;walls.push(physics.addBox({x,z,heading,width:.5,length:len+.15,friction:.12,restitution:.12,userData:{kind:'race-wall'}}));dummy.position.set(x,.5,z);dummy.rotation.y=heading;dummy.scale.set(1,1,len+.15);dummy.updateMatrix();wallMesh.setMatrixAt(cursor++,dummy.matrix);}wallMesh.instanceMatrix.needsUpdate=true;
 const ground=new T.Mesh(new T.PlaneGeometry(1600,1600),new T.MeshStandardMaterial({color:0x777956,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.set(path.originX,-.04,path.originZ);root.add(ground);
 const gates=[];for(let i=0;i<12;i++){path.sampleAtDistance(i*path.length/12,scratch);const gate=new T.Group();gate.position.set(scratch.x,0,scratch.z);gate.rotation.y=scratch.heading;const gm=new T.MeshBasicMaterial({color:i?0xdafa9b:0xfcaf17,transparent:true,opacity:.25});const parts=new T.InstancedMesh(new T.BoxGeometry(1,1,1),gm,3),transform=new T.Object3D();for(let part=0;part<3;part++){transform.position.set(part===2?0:part===0?-8:8,part===2?4:2,0);transform.scale.set(part===2?16:.12,part===2?.12:4,.12);transform.updateMatrix();parts.setMatrixAt(part,transform.matrix);}gate.add(parts);root.add(gate);gates.push(gate);}
 path.sampleAtDistance(0,scratch);const finish=new T.Group();finish.position.set(scratch.x,.035,scratch.z);finish.rotation.y=scratch.heading;root.add(finish);const tile=new T.BoxGeometry(.8,.008,.8),tileTransform=new T.Matrix4();for(let color=0;color<2;color++){const tiles=new T.InstancedMesh(tile,new T.MeshStandardMaterial({color:color?0x151b20:0xeeeeed,roughness:.9}),20);let cell=0;for(let row=0;row<2;row++)for(let col=0;col<20;col++)if((row+col)%2===color)tiles.setMatrixAt(cell++,tileTransform.makeTranslation(-7.6+col*.8,0,(row-.5)*.8));finish.add(tiles);}
 return {root,walls,gates,dispose(){for(const w of walls)physics.remove(w);root.removeFromParent();root.traverse(n=>{if(n.isMesh){n.geometry.dispose();if(!Array.isArray(n.material))n.material.dispose();}});}};
}
